"""Browser-owned Mitsubishi FX serial configuration and dispatch plans.

The server never opens a serial port in this transport mode.  It validates the
station profile and signs the exact bytes a foreground Edge/Chrome page may
write through Web Serial.
"""

from __future__ import annotations

import hashlib
import json
import re
from typing import Any, Mapping

try:
    from local_inspection_service.plc_fx_ascii import (
        CHECKSUM_EXCLUDE_ETX_LEGACY_VB,
        CHECKSUM_INCLUDE_ETX,
        CHECKSUM_INCLUDE_ETX_DOCUMENTED_COMMENT,
        CHECKSUM_MODES,
        PROTOCOL_ID,
        PlcConfigError,
        build_d206_frame,
        build_d_register_read_frame,
        build_d_register_write_frame,
        build_y04_frame,
        build_y_force_frame,
        logical_device_address,
        logical_force_y_address,
    )
except ModuleNotFoundError:  # pragma: no cover - direct script imports
    from plc_fx_ascii import (  # type: ignore[no-redef]
        CHECKSUM_EXCLUDE_ETX_LEGACY_VB,
        CHECKSUM_INCLUDE_ETX,
        CHECKSUM_INCLUDE_ETX_DOCUMENTED_COMMENT,
        CHECKSUM_MODES,
        PROTOCOL_ID,
        PlcConfigError,
        build_d206_frame,
        build_d_register_read_frame,
        build_d_register_write_frame,
        build_y04_frame,
        build_y_force_frame,
        logical_device_address,
        logical_force_y_address,
    )


LEGACY_WEB_SERIAL_SCHEMA_VERSION = 3
LEGACY_WEB_SERIAL_PROFILE_ID = "fx_ascii_16x16_test"
LEGACY_WEB_SERIAL_PROTOCOL_VERSION = "plc-web-serial-v3"
PREVIOUS_WEB_SERIAL_SCHEMA_VERSION = 4
PREVIOUS_WEB_SERIAL_PROFILE_ID = "fx_ascii_16x16_spec_v1"
WEB_SERIAL_SCHEMA_VERSION = 5
WEB_SERIAL_TRANSPORT_MODE = "web_serial"
WEB_SERIAL_PROFILE_ID = "mitsubishi_fx3ga_40mr"
WEB_SERIAL_PROTOCOL_VERSION = "plc-web-serial-v4"
WEB_SERIAL_PLAN_DEADLINE_SECONDS = 2.0
WEB_SERIAL_ACK_TIMEOUT_MS = 500
WEB_SERIAL_CONNECTING_LEASE_SECONDS = 60
WEB_SERIAL_ACTIVE_LEASE_SECONDS = 15
WEB_SERIAL_HEARTBEAT_SECONDS = 5
WEB_SERIAL_CAPTURE_POLL_INTERVAL_MS = 200

DEFAULT_WEB_SERIAL_CONFIG: dict[str, Any] = {
    "schema_version": WEB_SERIAL_SCHEMA_VERSION,
    "transport_mode": WEB_SERIAL_TRANSPORT_MODE,
    "profile_id": WEB_SERIAL_PROFILE_ID,
    "enabled": False,
    "protocol": PROTOCOL_ID,
    "checksum_mode": CHECKSUM_INCLUDE_ETX,
    "baudrate": 9600,
    "parity": "E",
    "data_bits": 7,
    "stop_bits": 1,
    "result_register": "D206",
    "output_control_point": "",
    "capture_trigger_enabled": False,
    "capture_input_register": "D205",
    "capture_trigger_value": 1,
    "capture_poll_interval_ms": WEB_SERIAL_CAPTURE_POLL_INTERVAL_MS,
    "ack_timeout_ms": WEB_SERIAL_ACK_TIMEOUT_MS,
    "retries": 0,
}

LEGACY_WEB_SERIAL_CONFIG: dict[str, Any] = {
    **DEFAULT_WEB_SERIAL_CONFIG,
    "schema_version": LEGACY_WEB_SERIAL_SCHEMA_VERSION,
    "profile_id": LEGACY_WEB_SERIAL_PROFILE_ID,
    "checksum_mode": CHECKSUM_EXCLUDE_ETX_LEGACY_VB,
}

PREVIOUS_WEB_SERIAL_CONFIG: dict[str, Any] = {
    **DEFAULT_WEB_SERIAL_CONFIG,
    "schema_version": PREVIOUS_WEB_SERIAL_SCHEMA_VERSION,
    "profile_id": PREVIOUS_WEB_SERIAL_PROFILE_ID,
    "output_control_point": "Y04",
}

WEB_SERIAL_CONFIG_FIELDS = frozenset(DEFAULT_WEB_SERIAL_CONFIG)
_D_RE = re.compile(r"D(?:0|[1-9][0-9]{0,2})", re.IGNORECASE)
_Y_RE = re.compile(r"Y(?:0[0-7]|1[0-7])", re.IGNORECASE)


def _strict_bool(value: Any, field: str) -> bool:
    if not isinstance(value, bool):
        raise PlcConfigError(f"{field} must be boolean")
    return value


def _strict_int(value: Any, field: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise PlcConfigError(f"{field} must be an integer")
    return value


def _normalize_web_serial_config(
    raw: Mapping[str, Any] | None,
    *,
    defaults: Mapping[str, Any],
    schema_version: int,
    profile_id: str,
    checksum_modes: frozenset[str],
) -> dict[str, Any]:
    source = dict(raw or {})
    unknown = set(source) - WEB_SERIAL_CONFIG_FIELDS
    if unknown:
        raise PlcConfigError(f"unknown Web Serial PLC fields: {sorted(unknown)}")
    config = {**defaults, **source}
    if _strict_int(config["schema_version"], "schema_version") != schema_version:
        raise PlcConfigError(f"schema_version must be {schema_version}")
    if config["transport_mode"] != WEB_SERIAL_TRANSPORT_MODE:
        raise PlcConfigError("transport_mode must be web_serial")
    if config["profile_id"] != profile_id:
        raise PlcConfigError("profile_id is not supported")
    if config["protocol"] != PROTOCOL_ID:
        raise PlcConfigError("protocol is not supported")
    if config["checksum_mode"] not in checksum_modes:
        raise PlcConfigError("checksum_mode is not allowed")
    if _strict_bool(config["enabled"], "enabled") not in {True, False}:
        raise PlcConfigError("enabled must be boolean")
    if _strict_int(config["baudrate"], "baudrate") != 9600:
        raise PlcConfigError("test profile requires baudrate 9600")
    if config["parity"] != "E":
        raise PlcConfigError("test profile requires even parity")
    if _strict_int(config["data_bits"], "data_bits") != 7:
        raise PlcConfigError("test profile requires 7 data bits")
    if _strict_int(config["stop_bits"], "stop_bits") != 1:
        raise PlcConfigError("test profile requires 1 stop bit")
    if _strict_int(config["ack_timeout_ms"], "ack_timeout_ms") != WEB_SERIAL_ACK_TIMEOUT_MS:
        raise PlcConfigError("test profile requires a 500ms ACK timeout")
    if _strict_int(config["retries"], "retries") != 0:
        raise PlcConfigError("Web Serial physical writes cannot be retried automatically")

    result_register = str(config["result_register"] or "").strip().upper()
    if not _D_RE.fullmatch(result_register):
        raise PlcConfigError("result_register must be D0 through D255")
    result_number = int(result_register[1:], 10)
    if not 0 <= result_number <= 255:
        raise PlcConfigError("result_register must be D0 through D255")
    result_register = f"D{result_number}"

    output_control_point = str(config["output_control_point"] or "").strip().upper()
    if output_control_point:
        if not _Y_RE.fullmatch(output_control_point):
            raise PlcConfigError("output_control_point must be Y00 through Y17 using octal digits")
        output_control_point = f"Y{int(output_control_point[1:], 8):02o}"

    capture_trigger_enabled = _strict_bool(config["capture_trigger_enabled"], "capture_trigger_enabled")
    capture_input_register = str(config["capture_input_register"] or "").strip().upper()
    if not _D_RE.fullmatch(capture_input_register):
        raise PlcConfigError("capture_input_register must be D0 through D255")
    capture_input_number = int(capture_input_register[1:], 10)
    if not 0 <= capture_input_number <= 255:
        raise PlcConfigError("capture_input_register must be D0 through D255")
    capture_input_register = f"D{capture_input_number}"
    if capture_input_register == result_register:
        raise PlcConfigError("capture_input_register must differ from result_register")
    capture_trigger_value = _strict_int(config["capture_trigger_value"], "capture_trigger_value")
    if not 0 <= capture_trigger_value <= 65535:
        raise PlcConfigError("capture_trigger_value must be 0 through 65535")
    if _strict_int(config["capture_poll_interval_ms"], "capture_poll_interval_ms") != WEB_SERIAL_CAPTURE_POLL_INTERVAL_MS:
        raise PlcConfigError("FX3GA profile requires a 200ms capture poll interval")

    return {
        **config,
        "result_register": result_register,
        "output_control_point": output_control_point,
        "capture_trigger_enabled": capture_trigger_enabled,
        "capture_input_register": capture_input_register,
        "capture_trigger_value": capture_trigger_value,
    }


def normalize_web_serial_config(raw: Mapping[str, Any] | None) -> dict[str, Any]:
    from .plc_modbus_rtu import PROFILE, PROTOCOL
    if (raw or {}).get("profile_id") == PROFILE:
        source = dict(raw or {})
        expected = {"protocol": PROTOCOL, "checksum_mode": "crc16", "baudrate": 19200, "data_bits": 8}
        if any(source.get(key) != value for key, value in expected.items()):
            raise PlcConfigError("XD5 requires Modbus RTU station 1, 19200/8E1")
        # Reuse logical D range, interlock, timeout and no-retry validation.
        translated = {**source, "profile_id": WEB_SERIAL_PROFILE_ID,
                      "protocol": PROTOCOL_ID, "checksum_mode": CHECKSUM_INCLUDE_ETX,
                      "baudrate": 9600, "data_bits": 7}
        validated = _normalize_web_serial_config(translated, defaults=DEFAULT_WEB_SERIAL_CONFIG,
            schema_version=WEB_SERIAL_SCHEMA_VERSION, profile_id=WEB_SERIAL_PROFILE_ID,
            checksum_modes=frozenset({CHECKSUM_INCLUDE_ETX}))
        if validated["output_control_point"]:
            raise PlcConfigError("XD5 initial adapter requires blank optional output")
        return {**validated, "profile_id": PROFILE, **expected}
    return _normalize_web_serial_config(
        raw,
        defaults=DEFAULT_WEB_SERIAL_CONFIG,
        schema_version=WEB_SERIAL_SCHEMA_VERSION,
        profile_id=WEB_SERIAL_PROFILE_ID,
        checksum_modes=frozenset({CHECKSUM_INCLUDE_ETX}),
    )


def normalize_legacy_web_serial_config(raw: Mapping[str, Any] | None) -> dict[str, Any]:
    return _normalize_web_serial_config(
        raw,
        defaults=LEGACY_WEB_SERIAL_CONFIG,
        schema_version=LEGACY_WEB_SERIAL_SCHEMA_VERSION,
        profile_id=LEGACY_WEB_SERIAL_PROFILE_ID,
        checksum_modes=frozenset({
            CHECKSUM_EXCLUDE_ETX_LEGACY_VB,
            CHECKSUM_INCLUDE_ETX_DOCUMENTED_COMMENT,
        }),
    )


def normalize_previous_web_serial_config(raw: Mapping[str, Any] | None) -> dict[str, Any]:
    return _normalize_web_serial_config(
        raw,
        defaults=PREVIOUS_WEB_SERIAL_CONFIG,
        schema_version=PREVIOUS_WEB_SERIAL_SCHEMA_VERSION,
        profile_id=PREVIOUS_WEB_SERIAL_PROFILE_ID,
        checksum_modes=frozenset({CHECKSUM_INCLUDE_ETX}),
    )


def migrate_web_serial_config(raw: Mapping[str, Any] | None) -> dict[str, Any]:
    """Migrate obsolete v3/v4 workstation configuration into schema v5."""
    source = dict(raw or {})
    if not source:
        return dict(DEFAULT_WEB_SERIAL_CONFIG)
    if (
        source.get("schema_version") == LEGACY_WEB_SERIAL_SCHEMA_VERSION
        or source.get("profile_id") == LEGACY_WEB_SERIAL_PROFILE_ID
    ):
        legacy = normalize_legacy_web_serial_config(source)
        return normalize_web_serial_config({
            **DEFAULT_WEB_SERIAL_CONFIG,
            "enabled": False,
            "result_register": legacy["result_register"],
            "output_control_point": legacy["output_control_point"],
        })
    if (
        source.get("schema_version") == PREVIOUS_WEB_SERIAL_SCHEMA_VERSION
        or source.get("profile_id") == PREVIOUS_WEB_SERIAL_PROFILE_ID
    ):
        previous = normalize_previous_web_serial_config(source)
        return normalize_web_serial_config({
            **DEFAULT_WEB_SERIAL_CONFIG,
            "enabled": previous["enabled"],
            "result_register": previous["result_register"],
            "output_control_point": previous["output_control_point"],
        })
    return normalize_web_serial_config(source)


def web_serial_resolved_addresses(config: Mapping[str, Any]) -> dict[str, str]:
    normalized = normalize_web_serial_config(config)
    if normalized["protocol"] == "modbus_rtu":
        return {"result_register": f'{int(normalized["result_register"][1:]):04X}',
                "capture_input_register": f'{int(normalized["capture_input_register"][1:]):04X}',
                "output_control_point": ""}
    return {
        "result_register": logical_device_address(normalized["result_register"]),
        "capture_input_register": logical_device_address(normalized["capture_input_register"]),
        "output_control_point": (
            logical_force_y_address(normalized["output_control_point"])
            if normalized["output_control_point"]
            else ""
        ),
    }


def build_web_serial_capture_read_plan(config: Mapping[str, Any], config_generation: int) -> dict[str, Any]:
    normalized = normalize_web_serial_config(config)
    register = normalized["capture_input_register"]
    if normalized["protocol"] == "modbus_rtu":
        from .plc_modbus_rtu import read_word
        frame = read_word(int(register[1:]))
    else:
        frame = build_d_register_read_frame(logical_device_address(register), normalized["checksum_mode"])
    return {
        "target": register,
        "operation": "read_capture_input",
        "frame_hex": frame.hex().upper(),
        "frame_sha256": hashlib.sha256(frame).hexdigest(),
        "expected_response_bytes": 7 if normalized["protocol"] == "modbus_rtu" else 8,
        "read_timeout_ms": normalized["ack_timeout_ms"],
        "poll_interval_ms": normalized["capture_poll_interval_ms"],
        "trigger_value": normalized["capture_trigger_value"],
        "config_generation": int(config_generation),
        "protocol_version": WEB_SERIAL_PROTOCOL_VERSION,
    }


def _frame_item(target: str, frame: bytes, operation: str) -> dict[str, Any]:
    frame_hex = frame.hex().upper()
    return {
        "target": target,
        "operation": operation,
        "frame_hex": frame_hex,
        "frame_sha256": hashlib.sha256(frame).hexdigest(),
        "expected_response_hex": "06",
    }


def build_web_serial_plan(config: Mapping[str, Any], passed: bool) -> list[dict[str, Any]]:
    normalized = normalize_web_serial_config(config)
    if normalized["protocol"] == "modbus_rtu":
        from .plc_modbus_rtu import write_word
        frame = write_word(int(normalized["result_register"][1:]), 1 if passed else 0)
        return [{**_frame_item(normalized["result_register"], frame, "write_result"),
                 "expected_response_hex": frame.hex().upper()}]
    checksum_mode = normalized["checksum_mode"]
    result_register = normalized["result_register"]
    frames = [
        _frame_item(
            result_register,
            build_d_register_write_frame(
                logical_device_address(result_register),
                1 if passed else 0,
                checksum_mode,
            ),
            "write_result",
        )
    ]
    output_control_point = normalized["output_control_point"]
    if output_control_point:
        frames.append(
            _frame_item(
                output_control_point,
                build_y_force_frame(output_control_point, bool(passed), checksum_mode),
                "set_output_on" if passed else "set_output_off",
            )
        )
    return frames


def build_web_serial_diagnostic_plan() -> list[dict[str, Any]]:
    """Return the fixed, administrator-only D206=6 write/read diagnostic."""
    register = "D206"
    address = logical_device_address(register)
    write = _frame_item(
        register,
        build_d_register_write_frame(address, 6, CHECKSUM_INCLUDE_ETX),
        "diagnostic_write",
    )
    read_frame = build_d_register_read_frame(address, CHECKSUM_INCLUDE_ETX)
    read = {
        "target": register,
        "operation": "diagnostic_read",
        "frame_hex": read_frame.hex().upper(),
        "frame_sha256": hashlib.sha256(read_frame).hexdigest(),
        "expected_response_hex": "02 + 4 ASCII HEX + 03 + SUM",
    }
    return [write, read]


def build_legacy_web_serial_plan(config: Mapping[str, Any], passed: bool) -> list[dict[str, Any]]:
    """Rebuild v3 frames solely for immutable historical verification."""
    normalized = normalize_legacy_web_serial_config(config)
    checksum_mode = normalized["checksum_mode"]
    result_register = normalized["result_register"]
    frames = [
        _frame_item(
            result_register,
            build_d206_frame(logical_device_address(result_register), bool(passed), checksum_mode),
            "write_result",
        )
    ]
    output_control_point = normalized["output_control_point"]
    if output_control_point:
        frames.append(
            _frame_item(
                output_control_point,
                build_y04_frame(logical_device_address(output_control_point), bool(passed), checksum_mode),
                "set_output_on" if passed else "set_output_off",
            )
        )
    return frames


def web_serial_config_fingerprint(config: Mapping[str, Any]) -> str:
    normalized = normalize_web_serial_config(config)
    material = json.dumps(normalized, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return hashlib.sha256(material.encode("ascii")).hexdigest()


def legacy_web_serial_config_fingerprint(config: Mapping[str, Any]) -> str:
    normalized = normalize_legacy_web_serial_config(config)
    material = json.dumps(normalized, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return hashlib.sha256(material.encode("ascii")).hexdigest()


def web_serial_profile_fingerprint(config: Mapping[str, Any]) -> str:
    normalized = normalize_web_serial_config(config)
    normalized["enabled"] = False
    material = json.dumps(normalized, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return hashlib.sha256(material.encode("ascii")).hexdigest()


def _connection_candidate(lease: Mapping[str, Any], config: Mapping[str, Any], check_id: str) -> dict[str, Any]:
    normalized = normalize_web_serial_config(config)
    frames = []
    for target in (normalized["capture_input_register"], normalized["result_register"]):
        if normalized["protocol"] == "modbus_rtu":
            from .plc_modbus_rtu import read_word
            frame = read_word(int(target[1:]))
        else:
            frame = build_d_register_read_frame(logical_device_address(target), normalized["checksum_mode"])
        frames.append({"target": target, "frame_hex": frame.hex().upper()})
    return {"id": check_id, "station_id": lease["station_id"], "session_id": lease["session_id"],
            "lease_epoch": lease["lease_epoch"], "config_generation": lease["config_generation"],
            "deadline_at": lease["expires_at"], "timeout_ms": WEB_SERIAL_ACK_TIMEOUT_MS,
            "frames": frames, "config": normalized,
            "serial_options": {"baudRate": normalized["baudrate"], "dataBits": normalized["data_bits"],
                               "stopBits": 1, "parity": "even", "flowControl": "none"}}


def build_connection_check(lease: Mapping[str, Any], config: Mapping[str, Any], check_id: str) -> dict[str, Any]:
    """Exactly two bounded profiles, no address/baud scan, no physical writes."""
    from .plc_modbus_rtu import PROFILE, PROTOCOL
    normalized = normalize_web_serial_config(config)
    primary = _connection_candidate(lease, normalized, check_id)
    if normalized["protocol"] == PROTOCOL:
        alternate = {**normalized, "profile_id": WEB_SERIAL_PROFILE_ID, "protocol": PROTOCOL_ID,
                     "checksum_mode": CHECKSUM_INCLUDE_ETX, "baudrate": 9600, "data_bits": 7,
                     "capture_trigger_enabled": False, "output_control_point": ""}
        suffix = "_fx"
    else:
        alternate = {**normalized, "profile_id": PROFILE, "protocol": PROTOCOL,
                     "checksum_mode": "crc16", "baudrate": 19200, "data_bits": 8,
                     "capture_trigger_enabled": False, "output_control_point": ""}
        suffix = "_rtu"
    primary["alternatives"] = [_connection_candidate(lease, alternate, check_id + suffix)]
    return primary


def validate_connection_check(lease: Mapping[str, Any], check_id: str | None, reads: list[Any], now: int) -> dict[str, Any]:
    from .plc_fx_ascii import parse_d_register_read_response
    from .plc_modbus_rtu import parse_word
    root = lease.get("connection_check") or {}
    plans = [root, *root.get("alternatives", [])]
    plan = next((item for item in plans if check_id and item.get("id") == check_id), {})
    if not plan:
        raise ValueError("plc_connection_verification_required_reload_page")
    if any(plan.get(key) != lease.get(key) for key in ("station_id", "session_id", "lease_epoch", "config_generation")):
        raise ValueError("plc_connection_check_fenced")
    if int(plan.get("deadline_at") or 0) <= now:
        raise ValueError("plc_connection_check_expired")
    if len(reads) != 2 or len(plan.get("frames", [])) != 2:
        raise ValueError("plc_connection_check_invalid_response")
    config = plan.get("config") or DEFAULT_WEB_SERIAL_CONFIG
    modbus = config.get("protocol") == "modbus_rtu"
    for frame, evidence in zip(plan["frames"], reads):
        evidence = evidence.model_dump() if hasattr(evidence, "model_dump") else evidence
        try:
            if evidence["target"] != frame["target"] or not re.fullmatch(r"[0-9A-Fa-f]{14}" if modbus else r"[0-9A-Fa-f]{16}", evidence["response_hex"]):
                raise ValueError("invalid response")
            (parse_word if modbus else parse_d_register_read_response)(bytes.fromhex(evidence["response_hex"]))
        except Exception as exc:
            raise ValueError("plc_connection_check_invalid_response") from exc
    return normalize_web_serial_config(config)
